insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('warheads-sour-watermelon', 'Sour Watermelon', 'Warheads', 'energy', 'sour', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Sour', 'Watermelon', 'Sharp finish']::text[], 'The one everybody starts on, and the one most people come back to. The sour hits in the first two seconds and then drops off into clean watermelon candy — it never turns chalky or bitter the way sour cans usually do by the halfway point.', 'The benchmark. Sour up front, clean all the way down.', 3, 4, 4, 2, array['warheads-sour-green-apple', 'sonic-ocean-water', 'citrus']::text[], 'Heavy lower days when you need something loud enough to cut through a pre-workout that''s already in your system.', array['#251419', '#7A2A38']::text[], 2021, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('warheads-sour-green-apple', 'Sour Green Apple', 'Warheads', 'energy', 'sour', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Sour', 'Green apple', 'Crisp']::text[], 'Drier and sharper than the watermelon — more green-apple skin than green-apple candy. It''s the most refreshing can in the lineup if you drink it cold, and the least forgiving if you let it warm up on the rack between sets.', 'Driest sour in the range. Drink it cold or don''t bother.', 2, 5, 4, 2, array['warheads-sour-watermelon', 'lemon-lime', 'citrus']::text[], 'Morning sessions where anything sweet sits badly on an empty stomach.', array['#161d15', '#3f6b30']::text[], 2022, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('warheads-sour-black-cherry', 'Sour Black Cherry', 'Warheads', 'energy', 'sour', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Sour', 'Dark cherry', 'Deep']::text[], 'Darker and rounder than the other two Warheads cans. The sourness sits underneath instead of on top, so it reads closer to a cherry soda than a sour candy. Divisive in the comments, quietly one of our best repeat sellers.', 'Cherry soda with a sour spine. Divisive, and we''re fine with that.', 3, 3, 3, 3, array['sonic-cherry-limeade', 'welchs-grape', 'warheads-sour-watermelon']::text[], 'Late-afternoon training when you want caffeine without something screaming at you.', array['#1c1013', '#5e1f2c']::text[], 2023, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('sour-patch-kids-redberry', 'Redberry', 'Sour Patch Kids', 'energy', 'candy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Candy', 'Mixed berry', 'Nostalgic']::text[], 'This is the closest any energy drink gets to actually tasting like the candy on the label. Mixed red berry, mild sour, no artificial aftertaste worth complaining about. If you''re buying one can to convince a friend that zero-sugar energy doesn''t have to taste like a vitamin, buy this one.', 'Tastes like the bag. The easiest can to hand a skeptic.', 4, 3, 3, 3, array['swedish-fish', 'sour-patch-kids-blue-raspberry', 'welchs-grape']::text[], 'Long sessions where you''re sipping across 90 minutes and flavor fatigue is real.', array['#1f1216', '#6d2331']::text[], 2022, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('sour-patch-kids-blue-raspberry', 'Blue Raspberry', 'Sour Patch Kids', 'energy', 'candy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Candy', 'Blue raspberry', 'Sweet']::text[], 'Sweeter and simpler than the Redberry. Blue raspberry is blue raspberry — there''s no complexity here and there doesn''t need to be. It''s the can we reach for when we''re already three sets deep and just want something cold and easy.', 'Straightforward blue raspberry. No notes, no surprises.', 4, 2, 3, 3, array['sour-patch-kids-redberry', 'bubblicious-cotton-candy', 'sonic-ocean-water']::text[], 'Anyone new to zero-sugar energy who bounced off the sour cans.', array['#101722', '#274a72']::text[], 2022, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('swedish-fish', 'Swedish Fish', 'Swedish Fish', 'energy', 'candy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Candy', 'Lingonberry', 'Chewy-sweet']::text[], 'The weirdest good flavor Ghost makes. That specific Swedish Fish taste — somewhere between lingonberry and raspberry — translated into a carbonated can without losing the plot. It shouldn''t work as a drink. It does.', 'Shouldn''t work as a drink. Somehow does.', 4, 1, 3, 4, array['sour-patch-kids-redberry', 'welchs-grape', 'warheads-sour-black-cherry']::text[], 'The can you bring to the gym when you want someone to ask what you''re drinking.', array['#20111a', '#742038']::text[], 2021, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('bubblicious-cotton-candy', 'Cotton Candy', 'Bubblicious', 'energy', 'candy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Candy', 'Cotton candy', 'Very sweet']::text[], 'Full commitment to the bit. This is the sweetest can in the lineup and it doesn''t pretend otherwise. A quarter of our customers rate it their favorite and the rest can''t finish one — there is almost no middle ground in our review data.', 'Sweetest can Ghost makes. You''ll love it or tap out at half.', 5, 1, 4, 4, array['bubblicious-original', 'orange-cream', 'sour-patch-kids-blue-raspberry']::text[], 'Cutting, when a sweet drink is doing real work keeping you out of the snack cupboard.', array['#1d1420', '#5c2a63']::text[], 2023, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('bubblicious-original', 'Original Bubble Gum', 'Bubblicious', 'energy', 'candy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Candy', 'Bubble gum', 'Retro']::text[], 'Pink bubble gum, exactly as you remember it, which is the whole appeal and the whole problem. Great for the first half of the can. Whether you finish it depends entirely on your relationship with gum.', 'Nails the gum. Whether that''s good is a personal matter.', 5, 1, 4, 4, array['bubblicious-cotton-candy', 'sour-patch-kids-blue-raspberry', 'orange-cream']::text[], 'Novelty runs and variety packs. Rarely anyone''s twelve-pack.', array['#20151c', '#6b3050']::text[], 2023, false);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('sonic-cherry-limeade', 'Cherry Limeade', 'Sonic', 'energy', 'soda', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Soda', 'Cherry', 'Lime']::text[], 'The lime does the heavy lifting. It keeps the cherry from going cough-syrup, which is where most cherry energy drinks end up. This is the most ''adult'' tasting can in the range and the one we recommend to people who say they don''t like energy drinks.', 'Lime keeps the cherry honest. The grown-up pick.', 3, 3, 3, 2, array['warheads-sour-black-cherry', 'lemon-lime', 'citrus']::text[], 'Hot days, outdoor sessions, anything where you want it to drink like a soda.', array['#1e1013', '#6b2029']::text[], 2023, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('sonic-ocean-water', 'Ocean Water', 'Sonic', 'energy', 'soda', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Soda', 'Coconut', 'Blue citrus']::text[], 'Coconut and blue citrus, light-bodied and genuinely refreshing. It''s the only can in the lineup we''d call easy — nothing about it fights you at rep twelve. Underrated by the internet, steadily top-five in our own reorder numbers.', 'The easy one. Nothing about it fights you mid-set.', 3, 2, 2, 2, array['warheads-sour-watermelon', 'tropical-mango', 'sour-patch-kids-blue-raspberry']::text[], 'High-volume days and long conditioning work where you''re drinking, not chugging.', array['#0f1a20', '#1f5a6e']::text[], 2023, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('orange-cream', 'Orange Cream', null, 'energy', 'creamy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Creamy', 'Orange', 'Vanilla']::text[], 'An orange creamsicle that carbonates without curdling the illusion. The vanilla is restrained enough to stay drinkable, which is more than most cream-flavored anything manages. Cold, it''s excellent. Warm, it''s a mistake.', 'Creamsicle that survives carbonation. Serve it cold.', 4, 1, 3, 5, array['citrus', 'bubblicious-cotton-candy', 'tropical-mango']::text[], 'Cold mornings and anyone who finds sour cans harsh before food.', array['#1d1813', '#6a4c33']::text[], 2021, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('citrus', 'Citrus', null, 'energy', 'citrus', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Citrus', 'Grapefruit', 'Dry']::text[], 'The least sweet can Ghost makes and the one most likely to become your default once the novelty of the candy flavors wears off. Grapefruit-forward, dry, almost bitter at the back. This is the twelve-pack people order on repeat.', 'Least sweet, most repeatable. The daily driver.', 2, 3, 2, 1, array['lemon-lime', 'warheads-sour-green-apple', 'sonic-cherry-limeade']::text[], 'Every day. This is the one you buy by the case when you drink one daily.', array['#1b1b17', '#5d5a3a']::text[], 2021, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('lemon-lime', 'Lemon Lime', null, 'energy', 'citrus', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Citrus', 'Lemon', 'Clean']::text[], 'Clean, simple, closer to a lemon-lime soda than anything candy-adjacent. It''s the can we recommend for stacking on top of a flavored pre-workout, because it doesn''t argue with whatever you already drank.', 'The neutral one. Stacks over any pre-workout without clashing.', 3, 3, 2, 1, array['citrus', 'warheads-sour-green-apple', 'sonic-cherry-limeade']::text[], 'Stacking days — when you''ve already had a flavored pre and don''t want a collision.', array['#181c12', '#4f6a22']::text[], 2021, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('tropical-mango', 'Tropical Mango', null, 'energy', 'fruit', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Fruit', 'Mango', 'Round']::text[], 'Ripe mango rather than mango candy, with enough acidity to stop it going flat. It''s a rounder, softer can — good when you want flavor without the sour edge, less good if you''re chasing a jolt.', 'Ripe, round, no sour edge. Flavor without the slap.', 4, 2, 3, 3, array['sonic-ocean-water', 'orange-cream', 'welchs-grape']::text[], 'Summer training blocks and anyone who finds the Warheads cans too aggressive.', array['#1e1811', '#6b4f2a']::text[], 2022, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('welchs-grape', 'Grape', 'Welch''s', 'energy', 'fruit', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Fruit', 'Grape', 'Juicy']::text[], 'Purple grape juice, carbonated, no apology. It avoids the medicinal grape problem almost entirely — you''ll know within one sip whether that''s your thing. Ours is a house-divided flavor and it always sells out of variety packs first.', 'Real grape juice energy. Sells out of variety packs first.', 4, 2, 3, 4, array['swedish-fish', 'sour-patch-kids-redberry', 'warheads-sour-black-cherry']::text[], 'Anyone who grew up on grape soda and never grew out of it.', array['#181022', '#452a6e']::text[], 2022, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('faze-pop', 'FaZe Pop', 'FaZe Clan', 'energy', 'candy', 200, 10, 0, array['L-Carnitine L-Tartrate', 'Alpha-GPC', 'NeuroFactor', 'Taurine', 'Vitamin B6', 'Vitamin B12']::text[], array['Candy', 'Blue pop', 'Sweet']::text[], 'A blue freezer-pop flavor built for a gaming audience, which means it''s sweet, cold-forward, and designed to be drunk slowly. It does fine in the gym — just know it was engineered for sitting still.', 'Freezer-pop sweet. Built for a desk, works fine on a rack.', 4, 2, 3, 3, array['sour-patch-kids-blue-raspberry', 'bubblicious-cotton-candy', 'sonic-ocean-water']::text[], 'Late sessions after a desk day, or anyone who came here from gaming content.', array['#111726', '#2c3f7d']::text[], 2022, false);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('hydration-warheads-sour-watermelon', 'Sour Watermelon', 'Warheads', 'hydration', 'sour', 0, 10, 0, array['Sodium', 'Potassium', 'Magnesium', 'Coconut water powder', 'Vitamin C']::text[], array['Zero caffeine', 'Electrolytes', 'Sour']::text[], 'Same flavor DNA as the energy can with the caffeine stripped out and electrolytes in. This is what you drink on the second session of the day when another 200 mg would wreck your sleep.', 'The 200 mg-free version of the flavor everyone starts on.', 3, 4, 3, 1, array['warheads-sour-watermelon', 'hydration-kiwi-strawberry']::text[], 'Two-a-days, evening sessions, and anyone already at their caffeine ceiling.', array['#251419', '#7A2A38']::text[], 2023, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('hydration-kiwi-strawberry', 'Kiwi Strawberry', null, 'hydration', 'fruit', 0, 10, 0, array['Sodium', 'Potassium', 'Magnesium', 'Coconut water powder', 'Vitamin C']::text[], array['Zero caffeine', 'Electrolytes', 'Light']::text[], 'Light, slightly tart, and easy to drink a lot of — which is the entire point of a hydration product. Nothing about it is trying to be exciting and that''s a compliment.', 'Boring on purpose. You''ll drink a litre without noticing.', 3, 2, 2, 1, array['hydration-blue-raspberry', 'citrus']::text[], 'Conditioning work, hot gyms, and anyone who sweats through a shirt by set three.', array['#141c14', '#3d6b3a']::text[], 2023, true);
insert into public.flavors (slug, name, collab, line, family, caffeine_mg, calories, sugar_g, actives, notes, tasting_note, short_take, sweetness, sourness, intensity, body, pairs_with, best_for, can_tone, release_year, core_lineup) values ('hydration-blue-raspberry', 'Blue Raspberry', null, 'hydration', 'fruit', 0, 10, 0, array['Sodium', 'Potassium', 'Magnesium', 'Coconut water powder', 'Vitamin C']::text[], array['Zero caffeine', 'Electrolytes', 'Sweet']::text[], 'The sweetest of the hydration flavors and the one most likely to get a teenager drinking water. Mixes cleanly into a shaker with intra-workout carbs if that''s your setup.', 'Sweet enough to actually finish the bottle.', 4, 2, 2, 1, array['hydration-kiwi-strawberry', 'sour-patch-kids-blue-raspberry']::text[], 'Intra-workout sipping and long sessions where plain water stops going down.', array['#101722', '#274a72']::text[], 2023, true);
