insert into public.product_variants (id, product_slug, pack_size, label, price_cents, compare_at_cents, affiliate_url, stripe_price_id, stripe_subscription_price_id, in_stock) values ('warheads-sour-black-cherry--1', 'warheads-sour-black-cherry', 1, 'Single can', 379, null, 'https://www.ghostlifestyle.com/search?q=Ghost+Energy+%E2%80%94+Warheads+Sour+Black+Cherry&ref=lifting4gains', null, null, true);
