insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (1, 'citrus', 'S', 'Wins on the only metric that matters long term: you can drink it every single day for a month and not get sick of it. Dry, grapefruit-forward, almost bitter at the back — it''s the only can here that behaves like a grown-up drink rather than a flavor demo.', 'Boring on first sip. Nobody''s ever shouted about it in a comment section.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (2, 'warheads-sour-watermelon', 'S', 'The flavor that made Ghost a gym staple. The sour lands hard and then clears, so you get the hit without the chalky aftertaste that ruins most sour cans by the halfway point. It''s the safest recommendation in the entire lineup.', 'It''s everywhere, which means it''s also the one you burn out on fastest.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (3, 'sonic-cherry-limeade', 'S', 'The lime is what saves it. Cherry energy drinks almost always slide into cough syrup and this one never gets close. Hand this to someone who says they hate energy drinks and watch them change their mind.', 'Lighter body means it disappears fast if you''re actually thirsty.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (4, 'sour-patch-kids-redberry', 'A', 'The most accurate candy translation anyone has managed in a can. Mixed red berry, gentle sour, no chemical aftertaste to speak of. It''s the best gateway flavor we sell and it earns its shelf space.', 'Sweet enough that a second can in one day is pushing it.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (5, 'sonic-ocean-water', 'A', 'Coconut and blue citrus, light on its feet, and the easiest can here to drink across a long session. The internet sleeps on it. Our reorder data does not — it sits top five every single month.', 'Too mild if you''re using the can as a wake-up rather than a drink.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (6, 'warheads-sour-green-apple', 'A', 'The sharpest, driest can in the range. Green apple skin rather than green apple candy, and the most genuinely refreshing thing here on a hot day.', 'Punishing if it warms up. Lukewarm, it''s the worst can in the lineup.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (7, 'lemon-lime', 'A', 'The utility player. It''s not going to be anyone''s favorite, but it''s the only can that layers cleanly over a flavored pre-workout without the two of them fighting. Stackers should keep a few around.', 'Genuinely plain. You are buying a function, not a flavor.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (8, 'tropical-mango', 'A', 'Ripe mango with enough acid to stay upright. It''s the best of the non-sour fruit cans and the right pick if the Warheads line feels like too much first thing in the morning.', 'Rounds off a bit flat by the bottom of the can.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (9, 'warheads-sour-black-cherry', 'B', 'Sour sits underneath the fruit instead of on top, which makes it read like a cherry soda with an edge. Comment sections hate it, repeat customers quietly keep buying it.', 'Doesn''t commit. Not sour enough for the sour crowd, not sweet enough for the candy crowd.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (10, 'swedish-fish', 'B', 'The most impressive piece of flavor engineering in the range. That specific lingonberry-raspberry thing survives carbonation intact. It has no business working and it works.', 'Novelty wears off around can four. Nobody''s daily driver.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (11, 'orange-cream', 'B', 'A creamsicle that doesn''t curdle the illusion when carbonated, with the vanilla dialled back far enough to stay drinkable. Excellent cold.', 'The heaviest body here. Sits badly if you''re doing anything with your lungs.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (12, 'sour-patch-kids-blue-raspberry', 'B', 'Blue raspberry, done competently, with no ambitions beyond that. Easy to drink and easy to forget.', 'The Redberry does the same job with more going on. Little reason to pick this over it.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (13, 'welchs-grape', 'B', 'Real grape juice energy that dodges the medicinal grape trap almost completely. A genuine house-divided flavor — and it''s always the first one gone from a variety pack.', 'One sip decides it for you forever. There''s no growing into this one.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (14, 'faze-pop', 'C', 'A blue freezer-pop built for a gaming audience, and you can taste the brief. It''s fine. It works on a rack, it just wasn''t designed for one.', 'Sweet and slow-drinking, which is the opposite of what you want mid-session.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (15, 'bubblicious-cotton-candy', 'C', 'Total commitment to the concept, and we respect it. A quarter of our customers rate it their number one. There''s no middle ground in our review data at all.', 'The sweetest can Ghost makes. Most people cannot finish one.');
insert into public.rankings (rank, flavor_slug, tier, verdict, knock) values (16, 'bubblicious-original', 'C', 'It nails pink bubble gum exactly. Whether that is an achievement or a warning depends entirely on how you feel about drinking gum.', 'Great for half a can. The second half is a chore for almost everyone.');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('warheads-sour-watermelon', 'Dev R.', 'Powerlifting, 6 yrs', 5, 'Doesn''t go chalky', 'I''ve been through every sour energy drink on the shelf and most of them turn into chalk by the halfway mark. This one clears. I keep a 24-pack under my desk and go through it in about three weeks.', true, 41, true, '2026-08-22T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('warheads-sour-watermelon', 'Kayla M.', 'CrossFit, 3 yrs', 4, 'Great, but I burned out on it', 'Was my daily for about four months and then one day I just couldn''t anymore. Still rate it a 4 because that''s on me, not the can. Swapped to Citrus and I''ll rotate back eventually.', true, 27, true, '2026-08-04T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('warheads-sour-watermelon', 'Tomas B.', 'Bodybuilding, 9 yrs', 5, 'Stacks fine over a half scoop', '200 mg on top of a half scoop of pre is about my ceiling and this sits fine on top of it. Full scoop plus a can and I''m jittery through my warmups, so plan accordingly.', true, 55, true, '2026-07-19T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('citrus', 'Priya N.', 'Olympic lifting, 2 yrs', 5, 'The only one I can drink daily', 'Everything else here is a candy flavor and I got tired of all of them. This is dry and slightly bitter and I''ve been on a 24-pack subscription since March without getting sick of it once.', true, 63, true, '2026-08-28T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('citrus', 'Jordan W.', 'General strength, 1 yr', 3, 'Took me three cans to get it', 'First can I thought it was bland. Third can I understood what everyone means. It''s not exciting, it just doesn''t wear you out. Three stars for the first impression, would be five now.', true, 38, true, '2026-06-11T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sour-patch-kids-redberry', 'Andre L.', 'Powerlifting, 4 yrs', 5, 'Converted my girlfriend', 'She said all energy drinks taste like batteries. Gave her this one and she finished the can. That''s the whole review.', true, 72, true, '2026-08-15T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sour-patch-kids-redberry', 'Mina S.', 'CrossFit, 5 yrs', 4, 'Perfect for long sessions', 'I sip one across a 90 minute class and it never gets old, which is more than I can say for the cotton candy. Losing a star because two in a day is genuinely too sweet.', true, 19, true, '2026-07-30T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sonic-ocean-water', 'Reggie T.', 'Strongman, 7 yrs', 5, 'Most underrated can they make', 'Nobody talks about this one and I don''t understand why. It''s light, it''s coconut-y, and it''s the only one I can drink during conditioning without feeling like I''ve swallowed syrup.', true, 34, true, '2026-09-02T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sonic-ocean-water', 'Hana K.', 'Hybrid training, 2 yrs', 4, 'Good, just mild', 'If you want a kick in the face this isn''t it. If you want something you can actually drink while you''re out of breath, it''s the best one here.', true, 15, true, '2026-08-09T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('warheads-sour-green-apple', 'Sam O.', 'General strength, 3 yrs', 5, 'Ice cold or nothing', 'Straight out of the fridge this is the best can in the range. Left in my gym bag for an hour it''s the worst. I''m not exaggerating, the temperature swing on this one is wild.', true, 48, true, '2026-08-19T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('warheads-sour-green-apple', 'Lucas D.', 'Powerlifting, 8 yrs', 4, 'Sourest one they make', 'If you found the watermelon too tame this is your can. It''s dry rather than sweet-sour, closer to apple skin. Took a couple to adjust.', true, 22, true, '2026-07-02T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sonic-cherry-limeade', 'Bianca F.', 'Running + lifting, 4 yrs', 5, 'Tastes like an actual drink', 'The lime stops it going medicinal, which is where every other cherry energy drink ends up. This is the one I bring to work because it doesn''t feel like a gym product.', true, 51, true, '2026-08-25T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('bubblicious-cotton-candy', 'Nate P.', 'Bodybuilding, 5 yrs', 5, 'I''m the guy who loves this', 'Everyone in my gym makes fun of me for it. I''m cutting, it''s zero sugar, it tastes like a dessert, and it keeps me out of the cupboard at 9pm. Easiest five stars I''ll ever give.', true, 66, true, '2026-08-12T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('bubblicious-cotton-candy', 'Elise V.', 'CrossFit, 6 yrs', 2, 'Could not finish it', 'Got halfway and poured it out. No fault in the product, it does exactly what it says, it''s just far too sweet for me to drink while training. Glad I bought a single and not a twelve.', true, 44, true, '2026-07-21T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('swedish-fish', 'Owen H.', 'General strength, 2 yrs', 4, 'It genuinely tastes like the candy', 'I don''t know how they did it. Everyone at my gym has asked for a sip. Marking it four because it''s a novelty for me rather than a rotation staple.', true, 29, true, '2026-08-06T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('welchs-grape', 'Carmen I.', 'Powerlifting, 3 yrs', 5, 'Grape soda kid, all grown up', 'Straight nostalgia. Doesn''t taste like medicine at all, which is the thing I was worried about. Always the first one I pull out of a variety pack.', true, 31, true, '2026-08-30T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('welchs-grape', 'Ty J.', 'Hybrid training, 5 yrs', 2, 'Not for me at all', 'One sip and I knew. Nothing wrong with it technically, grape just isn''t a thing I want carbonated. Traded the rest of my pack away at the gym in about ten minutes though, so someone''s happy.', true, 25, true, '2026-06-28T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('orange-cream', 'Fatima Z.', 'General strength, 4 yrs', 4, 'Best cold morning can', 'Sour stuff wrecks my stomach before food. This one doesn''t. Heavy though — I wouldn''t drink it before anything with running in it.', true, 20, true, '2026-08-17T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('lemon-lime', 'Greg M.', 'Powerlifting, 11 yrs', 4, 'The stacking can', 'I take a scoop of pre and then want something to drink through the session that doesn''t clash with it. This is that. Deliberately plain and that''s exactly why I buy it.', true, 36, true, '2026-07-14T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('tropical-mango', 'Ines C.', 'CrossFit, 2 yrs', 4, 'Good summer can', 'Tastes like actual mango rather than mango sweets. Goes a bit flat near the bottom but I''ve had way worse.', true, 12, true, '2026-08-01T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('warheads-sour-black-cherry', 'Malik A.', 'Bodybuilding, 6 yrs', 4, 'Better than the internet says', 'Read a lot of people dunking on this one so I expected the worst. It''s a cherry soda with a bit of an edge and I''m on my third twelve-pack. Don''t believe everything you read.', true, 40, true, '2026-08-21T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sour-patch-kids-blue-raspberry', 'Chloe B.', 'General strength, 1 yr', 4, 'Easy, no thinking required', 'It''s blue raspberry. It''s fine. It''s what I grab when I don''t want to make a decision. Sometimes that''s all you want from a can.', true, 9, true, '2026-07-09T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('faze-pop', 'Rhys E.', 'General strength, 2 yrs', 3, 'Fine, clearly made for gaming', 'Drinks slow and sweet. It''s alright on the rack but I can tell it wasn''t designed with a gym in mind. Bought it for the novelty, wouldn''t reorder.', true, 17, true, '2026-06-30T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('bubblicious-original', 'Dana Q.', 'CrossFit, 4 yrs', 3, 'Accurate to a fault', 'It tastes exactly like Bubblicious. That''s the review. Whether you want that in liquid form is a question you''ll have to answer yourself.', true, 23, true, '2026-07-25T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('hydration-warheads-sour-watermelon', 'Sasha U.', 'Two-a-days, 3 yrs', 5, 'Fixed my sleep', 'I was having a second energy at 6pm before evening sessions and sleeping terribly. Swapped to this and the problem went away. Same flavor, none of the caffeine.', true, 58, true, '2026-08-27T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('hydration-kiwi-strawberry', 'Bo N.', 'Hybrid training, 6 yrs', 4, 'Boring in the good way', 'You want your hydration drink to be unremarkable enough that you''ll drink a litre of it. This is that. No complaints.', true, 14, true, '2026-08-10T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('hydration-blue-raspberry', 'Teddy F.', 'General strength, 1 yr', 4, 'Gets my brother drinking water', 'He''s 16 and won''t touch plain water. He''ll finish a bottle of this. Worth it for that alone.', true, 21, true, '2026-07-28T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('sonic-cherry-limeade', 'Nadia R.', 'Olympic lifting, 5 yrs', 4, 'Goes down too fast', 'Light body means I finish it in about four sets. Great problem to have but budget accordingly if you''re on a long session.', true, 11, true, '2026-07-16T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('citrus', 'Marco V.', 'Strongman, 4 yrs', 5, 'Subscription and never thought about it again', '24 every month at 15% off. It shows up, I drink it, I don''t think about energy drinks anymore. That''s exactly what I wanted.', true, 46, true, '2026-09-04T12:00:00Z');
insert into public.reviews (product_slug, author, context, rating, title, body, verified_purchase, helpful_count, approved, created_at) values ('swedish-fish', 'Ali H.', 'Powerlifting, 2 yrs', 3, 'Impressive, not repeatable', 'Genuinely impressed by how close it is to the sweets. Also genuinely did not want a second one. Get it in a variety pack.', true, 26, true, '2026-06-19T12:00:00Z');
